export function listDecisionRangeId(params) {
  return api.get('/autonomy/AppDecision/listDecisionRangeId', { params })
}

// ============ 业主倡议（榆林版迁移）相关接口 ============
// 新增倡议（C 端发起，含发起人签字 signatureUrl）
export function addAppSuggest(data) {
  return api.post('/autonomy/suggest/addAppSuggest', data)
}
// 撤回倡议（含撤回签字 revocationSignatureUrl）
export function cancelSuggestV2(data) {
  return api.post('/autonomy/suggest/cancel', data)
}
// 判断当前登录人是否已响应
export function hasResponded(suggestId) {
  return api.get(`/autonomy/suggest/hasResponded/${suggestId}`)
}
// 倡议响应 / 撤回响应（共用接口，suggestResponseStatus: 1 响应、2 撤回）
export function appSuggestResponse(data) {
  return api.post('/autonomy/suggestResponse/appSuggestResponse', data)
}
// 根据小区id和议题id获取倡议分项列表
export function listSuggestTopicMatter(data) {
  return api.post('/autonomy/suggestTopicMatter/listByComplexIdAndTopicId', data)
}

